rule.example:

class Cart {
    private static decimal total;
    public static decimal AddToTotal(decimal amount) {
        return total + amount;        // implicit input: static state
    }
    public static bool IsLate() {
        return DateTime.Now.Hour > 17; // implicit input: the clock
    }
}


class Cart {
    private static decimal total;
    public static void AddToTotal(decimal amount) {
        Console.WriteLine(total);  // implicit output: console
        total += amount;           // implicit output: static state
    }
    public static void AddItem(List<string> cart, string item) {
        cart.Add(item);            // implicit output: changes the argument
    }
}
